/** V76 — cenas V63 com refinamentos e overlays pontuais. */
import {V63_SCENE_MEDIA} from './scene-assets-v63.js?v=84.5';
import {V63_SCENE_META} from './scene-v63-data.js?v=84.5';
import {montar} from './addons/cenarios_miticos/integracao/cenarios_miticos_v7.js';
import {CARTOON_SCENES,mountBikiniBottom} from './addons/cenarios_desenhos/cartoon-scenes.js';
const MYTHIC_SCENES={
 ceu_arco_iris:{label:'Céu do Arco-Íris',background:'ceu/cenario.webp',fill:'#859bcc'},
 cthulhu_fofinho:{label:'Cthulhu Fofinho',background:'cthulhu/cenario.webp',fill:'#335a73'},
 clareira_lunar:{label:'Clareira Lunar',background:'clareira_lunar/cenario.webp',fill:'#242051'}
};
const mythicRoot=new URL('./addons/cenarios_miticos/',import.meta.url);
const animatedStages=new WeakMap();
const BIKINI_SCENE='fenda_do_bikini';
export const SCENE_KEYS=[...Object.keys(V63_SCENE_MEDIA).filter(key=>!['bedroom','kitchen'].includes(key)),...Object.keys(MYTHIC_SCENES),...Object.keys(CARTOON_SCENES)];
export const SCENE_LABELS={
 ...Object.fromEntries(Object.entries(V63_SCENE_META).map(([key,scene])=>[key,scene.title])),
 ...Object.fromEntries(Object.entries({...MYTHIC_SCENES,...CARTOON_SCENES}).map(([key,scene])=>[key,scene.label]))
};
const SKY={garden:'#cfe6e7',sunset:'#dcad96',night:'#3e4565',beach:'#b8dfe9',desert:'#e4c6b7',forest:'#628f85',snow:'#a8b8d0',space:'#1c2442',sea:'#6aa3bc',halloween:'#4a4868',christmas:'#859eaf',bedroom:'#baa6b3',kitchen:'#c0cec4'};
const FRAME_MS=145,FRAME_COUNT=40;
const normalize=key=>key==='clouds'?'desert':(V63_SCENE_MEDIA[key]?key:'garden');
const ORBIT_DATA=JSON.parse(document.getElementById('v77-orbit-media')?.textContent||'{}');
// Data URI made into a Blob URL to avoid huge repeated attributes in miniature cards.
function orbitUrl(data){
 if(!data?.startsWith('data:'))return data||'';
 try{const pos=data.indexOf(',');const type=data.slice(5,pos).split(';')[0]||'image/gif';
 const bin=atob(data.slice(pos+1));const out=new Uint8Array(bin.length);
 for(let i=0;i<bin.length;i++)out[i]=bin.charCodeAt(i);
 return URL.createObjectURL(new Blob([out],{type}));}
 catch{return data;}
}
const ORBIT={planet:orbitUrl(ORBIT_DATA.planet),comet:orbitUrl(ORBIT_DATA.comet)};
const SLEIGH_SRC=orbitUrl(document.getElementById('v844-sleigh')?.textContent||'');
const SLEIGH_NODES=`<img class="v844-sleigh" src="${SLEIGH_SRC}" alt="" aria-hidden="true" decoding="async">`;
const SPACE_NODES=`<img class="v77-orbit-planet" src="${ORBIT.planet}" alt="" aria-hidden="true" decoding="async">
  <span class="v77-orbit-comet v77-orbit-comet-a"><img src="${ORBIT.comet}" alt="" aria-hidden="true"></span>
  <span class="v77-orbit-comet v77-orbit-comet-b"><img src="${ORBIT.comet}" alt="" aria-hidden="true"></span>`;
// Slots centralizados em áreas livres. Dimensões do fantasma após -15%: ~58x65px.
// Resguarda morcego (esquerda superior), pet (centro), casa (direita baixa) e abóbora.
const GHOST_SAFE_SPOTS=[[156,38],[192,42],[235,42],[257,52],[260,118],[83,184],[91,205],[205,30]];
const GHOST_SEED=Math.floor(Math.random()*0x7fffffff);
const GHOST_CYCLE_MS=15000; // V84.22: ciclo total de aparecimento e desaparecimento = 15 segundos
function halloweenGhostPosition(elapsed){
 const cycle=Math.floor(Math.max(0,elapsed)/GHOST_CYCLE_MS);
 const hash=Math.imul((cycle+GHOST_SEED+1)|0,1103515245)>>>0;
 const spot=GHOST_SAFE_SPOTS[(hash>>>12)%GHOST_SAFE_SPOTS.length];
 const dx=((hash>>>3)%7)-3,dy=((hash>>>7)%7)-3;
 return {x:spot[0]+dx,y:spot[1]+dy,visible:true};
}
// Miniaturas e criação não chamam updateSceneMarkers; animam-se de forma independente.
setInterval(()=>{
 for(const ghost of document.querySelectorAll('.v64-overlay-ghost')){
  const stage=ghost.closest('.v64-scene-stage');
  if(!stage || stage.querySelector('.v64-gaze-marker'))continue;
  const start=Number(ghost.dataset.ghostStart)||Date.now();
  const cycle=Math.floor(Math.max(0,Date.now()-start)/GHOST_CYCLE_MS);
  if(ghost.dataset.ghostCycle===String(cycle))continue;
  const p=halloweenGhostPosition((cycle + (Number(ghost.dataset.ghostSalt)||0))*GHOST_CYCLE_MS);
  ghost.style.left=`${p.x/3.2}%`;
  ghost.style.top=`${p.y/3.2}%`;
  ghost.dataset.ghostCycle=String(cycle);
 }
},1200);

const OVERLAYS={
  halloween:`<img class="v64-scene-overlay v64-overlay-ghost" src="data:image/gif;base64," alt="" aria-hidden="true">`,
  christmas:`<img class="v64-scene-overlay v64-overlay-santa" src="data:image/gif;base64," alt="" aria-hidden="true">`
};
export function sceneMarkup(scene,animated=false){
 const extra=MYTHIC_SCENES[scene]??CARTOON_SCENES[scene];
 if(extra)return `<div class="v64-scene-stage" data-v64-scene="${scene}"><img class="v64-scene-frame" src="${new URL(extra.background,mythicRoot)}" draggable="false" alt="" decoding="async" loading="${animated==='preview'?'lazy':'eager'}"></div>`;
 scene=normalize(scene);
 const media=V63_SCENE_MEDIA[scene];
 const isAnimated=animated===true||animated==='creator'||animated==='preview';
 const picture=animated==='preview'?media.preview:(isAnimated?media.gif:media.still);
 const nodes=isAnimated&&animated===true?V63_SCENE_META[scene].objects.map(o=>`<span class="v64-gaze-marker" data-v64-object="${o.key}" aria-hidden="true" style="left:${(o.x+o.w/2)/3.2}%;top:${(o.y+o.h/2)/3.2}%"></span>`).join(''):'';
 const overlay=(scene==='christmas'?SLEIGH_NODES:(OVERLAYS[scene]||''))+(scene==='space'?SPACE_NODES:'');
 // V84.14: luz externa sempre ativa (inclusive miniatura e tela inicial).
 // V84.29: cada luminaria e uma camada animada RGBA real, sem retangulo
 // branco, e o GIF base ja vem sem a antiga luminaria embutida.
 const lanternOverlay=(scene==='night'||scene==='sunset')
   ? `<img class="v8429-lantern v8429-lantern-${scene}" src="./assets/v8429/${scene}_animated.gif" alt="" draggable="false" aria-hidden="true" decoding="async">`
   : '';
 const lanternHalo=scene==='sunset' ? '<span class="v8414-lantern-halo v8414-halo-sunset" aria-hidden="true"></span>' : (scene==='night' ? '<span class="v8414-lantern-halo v8414-halo-night" aria-hidden="true"></span>' : '');
 const salt=Math.floor(Math.random()*8);
 const g=halloweenGhostPosition(salt*GHOST_CYCLE_MS);
 const ghostAttrs=`class="v64-scene-overlay v64-overlay-ghost" data-ghost-cycle="0" data-ghost-salt="${salt}" data-ghost-start="${Date.now()}" style="left:${g.x/3.2}%;top:${g.y/3.2}%"`;
 const adjustedOverlay=scene==='halloween'?overlay.replace('class="v64-scene-overlay v64-overlay-ghost"',ghostAttrs):overlay;
 return `<div class="v64-scene-stage" data-v64-scene="${scene}" style="--v64-sky:${SKY[scene]}"><img class="v64-scene-frame" src="${picture}" draggable="false" alt="" decoding="async" loading="${animated==='preview'?'lazy':'eager'}">${adjustedOverlay}${lanternHalo}${lanternOverlay}${nodes}</div>`;
}
export function sceneFill(scene){return MYTHIC_SCENES[scene]?.fill??CARTOON_SCENES[scene]?.fill??SKY[normalize(scene)];}
export function startBikiniSpeech(host){
 const mounted=animatedStages.get(host);
 return mounted?.scene===BIKINI_SCENE?mounted.player.speak():undefined;
}
export function unmountScene(host){
 animatedStages.get(host)?.player.destruir();
 animatedStages.delete(host);
}
export function renderScene(host,scene,mode){
 if(animatedStages.get(host)?.scene===scene)return;
 unmountScene(host);
 host.style.setProperty('--v64-scene-sky',sceneFill(scene));
 host.innerHTML=sceneMarkup(scene,mode);
 if(scene===BIKINI_SCENE){
  animatedStages.set(host,{scene,player:mountBikiniBottom(host.firstElementChild)});
  return;
 }
 if(!Object.hasOwn(MYTHIC_SCENES,scene))return;
 const stage=host.firstElementChild;
 const player=montar(stage,{scene});
 stage.querySelector('.v64-scene-frame').remove();
 animatedStages.set(host,{scene,player});
}
export function cometCycle(elapsed){
 const ms=((elapsed%60000)+60000)%60000;
 const travel=25800/1.4; // velocidade 40% maior, mantendo o período de 60 segundos
 const start=ms<30000?0:30000;
 const local=ms-start;
 const first=start===0;
 const visible=local>=858 && local<travel;
 // Mesmo percurso, escala e transparência das keyframes CSS;
 // o olhar do pet só pode seguir um cometa presente na tela.
 const stops=first
   ? [[858,84,11,1],[5142,79,22,.90],[10716,72,33,.73],[16716,66,45,.42],[travel,60.5,55.2,.05]]
   : [[858,2,11,1],[5142,9,22,.86],[10716,18,33,.66],[16716,29,45,.28],[travel,32.5,55.5,.05]];
 if(!visible)return {x:first?292:30,y:118,visible:false};
 let i=0;
 while(i<stops.length-2 && local>stops[i+1][0])i++;
 const a=stops[i],b=stops[i+1];
 const f=Math.max(0,Math.min(1,(local-a[0])/(b[0]-a[0])));
 const lerp=(j)=>a[j]+(b[j]-a[j])*f;
 const scale=lerp(3);
 return {x:(lerp(1)+8.5*scale)*3.2,y:(lerp(2)+9.5*scale)*3.2,visible:true};
}
export function sceneMarkerPosition(object,frame,elapsed=frame*FRAME_MS){
 if(object.key==='christmas__sleigh'){
  const phase=((elapsed%60000)+60000)%60000/60000;
  if(phase>=.15 && phase<.65 || phase>=.81)return {x:320,y:45,visible:false};
  // Flight 1: left-to-right; flight 2: right-to-left. The pet never watches offscreen.
  const x=phase<.15 ? -24+(128*phase/.15) : 110-(137*(phase-.65)/.15);
  const y=9+2*Math.sin(phase*2*Math.PI);
  return {x:(x+8)*3.2,y:(y+5)*3.2,visible:phase>.012&&phase<.81};
 }
 if(object.key==='forest__squirrel'){
  const f=Math.floor(Math.max(0,elapsed)/260)%40;
  let x=256;
  if(f<11)x=256+2*Math.sin(Math.PI*f/10);
  else if(f<21){const t=(f-11)/10;x=256-28*t*t*(3-2*t);}
  else if(f<28)x=228+2*Math.sin(Math.PI*(f-21)/7);
  else {const t=(f-28)/12;x=228+28*t*t*(3-2*t);}
  return {x:x+27,y:246+1.6*Math.sin(f*Math.PI/10+.8)+27,visible:true};
 }
 if(object.key==='sea__jelly'){
   const th=2*Math.PI*((frame%40)+40)%40/40;
   return {x:18+5*Math.sin(th)+22,y:118+12*Math.sin(th+.5)+25,visible:true};
 }
 if(object.key==='sea__fish'){
   const t=((frame%40)+40)%40;
   const q=t<=20?t/20:(40-t)/20;
   const pp=q*q*(3-2*q);
   return {x:246-(246-112)*pp+22,y:115+9*Math.sin(2*Math.PI*t/40+.8)+25,visible:true};
 }
 if(object.key==='halloween__bat'){
   const th=2*Math.PI*((frame%40)+40)%40/40;
   return {x:15+8*Math.sin(th+.8)+30.5,y:81+6*Math.sin(2*th)+34.5,visible:true};
 }
 if(object.key==='halloween__ghost')return halloweenGhostPosition(elapsed);
 if(object.key==='snow__snowman'){const t=Math.floor(Math.max(0,elapsed)/145)%10;return {x:object.x+object.w/2+Math.sin(2*Math.PI*t/10)*.7,y:object.y+object.h/2-.8*Math.sin(2*Math.PI*t/10),visible:true};}
 if(object.key==='night__owl'){const t=((frame%40)+40)%40;const q=t<=20?t/20:(40-t)/20;const pp=q*q*(3-2*q);return {x:28+(248-28)*pp+object.w/2,y:58+10*Math.sin(2*Math.PI*t/40+.5)+6*Math.cos(4*Math.PI*t/40+.7)+object.h/2,visible:true};}
 if(object.key==='space__comet')return cometCycle(elapsed);
 const t=((frame%FRAME_COUNT)+FRAME_COUNT)%FRAME_COUNT;
 const ping=(a,b,phase=0)=>{
   const tt=(t+phase)%FRAME_COUNT;
   const q=tt<=FRAME_COUNT/2?tt/(FRAME_COUNT/2):(FRAME_COUNT-tt)/(FRAME_COUNT/2);
   const p=q*q*(3-2*q);
   return {value:Math.round(a+(b-a)*p),tt};
 };
 if(object.key==='garden__butterfly'){
   const th=2*Math.PI*t/FRAME_COUNT;
   const x=Math.round(150+105*Math.cos(th));
   const y=Math.round(102+16*Math.sin(th+0.2));
   return {x:x+14.5,y:y+12.5,visible:true};
 }
 if(object.key==='sunset__birds'){
   const p=ping(14,258);
   const y=Math.round(34 + 5*Math.sin(2*Math.PI*p.tt/FRAME_COUNT+0.5) - 3*Math.sin(4*Math.PI*p.tt/FRAME_COUNT));
   return {x:p.value+object.w/2,y:y+object.h/2,visible:true};
 }
 if(object.key==='beach__gull'){
   const p=ping(16,258);
   const y=Math.round(34 + 5*Math.sin(2*Math.PI*p.tt/FRAME_COUNT+0.2) - 2*Math.sin(4*Math.PI*p.tt/FRAME_COUNT));
   return {x:p.value+object.w/2,y:y+object.h/2,visible:true};
 }
 if(object.key==='beach__crab'){
   const p=ping(252,16);
   return {x:p.value+object.w/2,y:252+object.h/2,visible:true};
 }
 if(object.key==='desert__lizard'){
   const p=ping(220,262);
   const y=Math.round(250 + Math.sin(2*Math.PI*p.tt/FRAME_COUNT));
   return {x:p.value+object.w/2,y:y+object.h/2,visible:true};
 }
 let x=object.x,y=object.y;
 if(object.trajectory){
   const q=t<=FRAME_COUNT/2?t/(FRAME_COUNT/2):(FRAME_COUNT-t)/(FRAME_COUNT/2),pp=q*q*(3-2*q);
   x=Math.round(object.trajectory.x[0]+(object.trajectory.x[1]-object.trajectory.x[0])*pp);
   y=Math.round(object.trajectory.y[0]+(object.trajectory.y[1]-object.trajectory.y[0])*pp+3*Math.sin(2*Math.PI*t/FRAME_COUNT));
 }
 return {x:x+object.w/2,y:y+object.h/2,visible:true};
}
export function updateSceneMarkers(stage,elapsed){
 if(!stage)return 0;
 const scene=stage.dataset.v64Scene,details=V63_SCENE_META[scene];
 if(!details)return 0;
 const frame=Math.floor(Math.max(0,elapsed)/FRAME_MS)%FRAME_COUNT;
 stage.dataset.frame=String(frame);
 const markers=stage.querySelectorAll('.v64-gaze-marker');
 let ghostMarker=null;
 markers.forEach((node,i)=>{
  const p=sceneMarkerPosition(details.objects[i],frame,elapsed);
  const ghost=details.objects[i]?.key==='halloween__ghost';
  const ghostAge=((elapsed%GHOST_CYCLE_MS)+GHOST_CYCLE_MS)%GHOST_CYCLE_MS;
  const ghostPhase=ghostAge/GHOST_CYCLE_MS;
  const ghostOpacity=ghostPhase<.12 ? 0 : ghostPhase<.20 ? (ghostPhase-.12)/.08 : ghostPhase<.44 ? 1 : ghostPhase<.56 ? 1-.1*(ghostPhase-.44)/.12 : ghostPhase<.68 ? .9*(.68-ghostPhase)/.12 : 0;
  const visible=p.visible&&(!ghost||ghostOpacity>.01);
  if(ghost)stage.dataset.ghostOpacity=String(ghostOpacity);
  node.style.opacity=visible?'1':'0';
  node.style.left=`${p.x/3.2}%`;node.style.top=`${p.y/3.2}%`;
  if(ghost)ghostMarker={x:p.x,y:p.y,visible};
 });
 if(scene==='halloween'){
  const ghostEl=stage.querySelector('.v64-overlay-ghost');
  if(ghostEl && ghostMarker){
   ghostEl.style.left=`${ghostMarker.x/3.2}%`;
   ghostEl.style.top=`${ghostMarker.y/3.2}%`;
   ghostEl.style.opacity=ghostMarker.visible?String(.85*(Number(stage.dataset.ghostOpacity)||0)):'0';
  }
 }
 return frame;
}
export function prioritySceneMarkers(stage){
 if(!stage)return [];
 const items=[...stage.querySelectorAll('.v64-gaze-marker')];
 const details=V63_SCENE_META[stage.dataset.v64Scene]?.objects||[];
 const visible=items.filter(item=>item.style.opacity!=='0');
 const moving=item=>{const obj=details.find(d=>d.key===item.dataset.v64Object);return Boolean(obj?.trajectory||obj?.key==='space__comet');};
 return visible.sort((a,b)=>Number(moving(b))-Number(moving(a)));
}
